def render_icon(name: str, size: int = 15, cls: str = "") -> Markup:
    """Render an inline SVG icon safely with zero external font or CDN requests."""
    body = _ICONS.get(name, _ICONS["database"])
    safe_size = max(10, min(48, int(size)))
    class_attr = f' class="dk-icon {escape(cls)}"' if cls else ' class="dk-icon"'
    return Markup(
        f'<svg{class_attr} width="{safe_size}" height="{safe_size}" viewBox="0 0 24 24" '
        'fill="none" stroke="currentColor" stroke-width="1.75" '
        f'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{body}</svg>'
    )
